#!/usr/bin/env bash
# recipes/crate-windows-aarch64-gnullvm--0-52-0/build.sh -- stage the windows_aarch64_gnullvm 0.52.0 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/windows_aarch64_gnullvm-0.52.0"
